int main(void){TitanThemeV4Scene s;TitanThemeV4FrameInput i;TitanThemeV4Telemetry t;TitanThemeV4EvaluatedLayer e;assert(TitanThemeV4_ParseCompiled(manifest,&s));assert(s.layer_count==3&&s.declared_bytes==40960u);assert(s.layers[0].z==0&&s.layers[2].z==20);memset(&i,0,sizeof(i));i.context=TITAN_THEME_V4_CONTEXT_HOME;i.navigation=10.0f;i.elapsed_ms=1000;TitanThemeV4_SetDegradation(TITAN_THEME_V4_DEGRADE_NONE);TitanThemeV4_EvaluateScene(&s,&i,&t);assert(t.visible_layers==3&&t.static_layers==1&&t.animated_layers==2);assert(TitanThemeV4_EvaluateLayer(&s.layers[1],&i,&e)&&e.visible&&e.x!=s.layers[1].x);TitanThemeV4_SetDegradation(TITAN_THEME_V4_DEGRADE_DECORATIVE);TitanThemeV4_EvaluateScene(&s,&i,&t);assert(t.visible_layers==2&&t.skipped_layers==1);TitanThemeV4_SetDegradation(TITAN_THEME_V4_DEGRADE_ENHANCED);TitanThemeV4_EvaluateScene(&s,&i,&t);assert(t.visible_layers==1&&t.static_layers==1);puts("theme-v4-runtime: OK fixed parse/sort/parallax/degradation/telemetry");return 0;}
